-- ── THE TWO HUNKS, each once on the live body and each reversing to its pre-image ──────────────
--   1. voyage.water_roadstead answers the drawn roadstead for its quay.
--   2. public.npc_coast_legs reads a coast course backwards whole: it took the two points of a straight
--      line (0400), and a coast course re-sailed round the land has more than two.
do $$
declare
  c_fns constant text[] := array['voyage.water_roadstead(numeric,numeric)', 'public.npc_coast_legs(uuid)'];
  h      record;
  v_pre  text;
  v_meta text;
  v_def  text;
  v_n    int;
  v_others text;
begin
  create temp table hunk_0440 (ord int primary key, fn text, old text, new text) on commit drop;
  insert into hunk_0440 values
  (1, c_fns[1],
$h$begin
  select * into r from public.sea_raster where id = 1;
$h$,
$h$begin
  -- 0440: THE ROADS ON THE WATER. A quay whose raster roadstead lies on the land the chart draws is
  -- reached from its drawn roadstead (voyage.drawn_roadsteads), measured on the chart's own tiles.
  select d.lat, d.lon into lat, lon from voyage.drawn_roadsteads d where d.quay_lat = p_lat and d.quay_lon = p_lon;
  if found then
    nm := voyage.gc_distance_nm(p_lat::float8, p_lon::float8, lat::float8, lon::float8)::numeric;
    channel := null;
    return next;
    return;
  end if;
  select * into r from public.sea_raster where id = 1;
$h$),
  (2, c_fns[2],
$h$select c.from_port, jsonb_build_array(c.course -> 1, c.course -> 0), c.nm from public.npc_coast_courses c$h$,
$h$select c.from_port, (select jsonb_agg(t.x order by t.i desc) from jsonb_array_elements(c.course) with ordinality t(x, i)), c.nm from public.npc_coast_courses c$h$);
  create temp table pre_0440 on commit drop as
  select f as fn, replace(pg_get_functiondef(f::regprocedure), E'\r', '') as def,
         (select coalesce(p.proacl::text, '') || ':' || p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, '') || ':' || p.proowner::text
            from pg_proc p where p.oid = f::regprocedure) as meta
    from unnest(c_fns) f;
  select md5(string_agg(p.oid::regprocedure::text || ':' || md5(replace(pg_get_functiondef(p.oid), E'\r', '')) || ':' || coalesce(p.proacl::text, ''), ',' order by p.oid::regprocedure::text))
    into v_others
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname in ('public', 'cmd', 'world', 'voyage') and p.prokind in ('f', 'p')
     and not exists (select 1 from unnest(c_fns) f where f::regprocedure = p.oid);
  for h in select * from hunk_0440 order by ord loop
    v_pre := replace(pg_get_functiondef(h.fn::regprocedure), E'\r', '');
    v_n := (length(v_pre) - length(replace(v_pre, h.old, ''))) / length(h.old);
    if v_n <> 1 then
      raise exception '0440 self-assert FAIL: hunk % of % occurs % time(s), not once: the deployed body is not what this file was written against', h.ord, h.fn, v_n;
    end if;
    execute replace(v_pre, h.old, h.new);
    v_def := replace(pg_get_functiondef(h.fn::regprocedure), E'\r', '');
    if (length(v_def) - length(replace(v_def, h.new, ''))) / length(h.new) <> 1 then
      raise exception '0440 self-assert FAIL: hunk % is not in the new body of % once', h.ord, h.fn;
    end if;
    if (select coalesce(p.proacl::text, '') || ':' || p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, '') || ':' || p.proowner::text
          from pg_proc p where p.oid = h.fn::regprocedure) <> (select p.meta from pre_0440 p where p.fn = h.fn) then
      raise exception '0440 self-assert FAIL: the grants, volatility, definer, search path or owner of % moved', h.fn;
    end if;
  end loop;
  for h in select p.fn, p.def from pre_0440 p loop
    v_def := replace(pg_get_functiondef(h.fn::regprocedure), E'\r', '');
    for v_n in select x.ord from hunk_0440 x where x.fn = h.fn order by x.ord desc loop
      v_def := replace(v_def, (select x.new from hunk_0440 x where x.ord = v_n), (select x.old from hunk_0440 x where x.ord = v_n));
    end loop;
    if v_def <> h.def then
      raise exception '0440 self-assert FAIL: % does not reverse to its pre-image', h.fn;
    end if;
  end loop;
  if (select md5(string_agg(p.oid::regprocedure::text || ':' || md5(replace(pg_get_functiondef(p.oid), E'\r', '')) || ':' || coalesce(p.proacl::text, ''), ',' order by p.oid::regprocedure::text))
        from pg_proc p join pg_namespace n on n.oid = p.pronamespace
       where n.nspname in ('public', 'cmd', 'world', 'voyage') and p.prokind in ('f', 'p')
         and not exists (select 1 from unnest(c_fns) f where f::regprocedure = p.oid)) <> v_others then
    raise exception '0440 self-assert FAIL: another function moved';
  end if;
end
$$;

-- The roadstead each harbour is reached from: what voyage.water_roadstead now answers for its quay.
update public.sea_reaches sr
   set roadstead_lat = w.lat, roadstead_lon = w.lon, snap_nm = w.nm
  from public.ports p
 cross join lateral voyage.water_roadstead(p.lat, p.lon) w
 where p.id = sr.port_id and p.code in ('ALG', 'AMB', 'ANC', 'ANG', 'BAN', 'BAS', 'BRI', 'CEU', 'CHS', 'CID', 'CON', 'COR', 'DGA', 'DIU', 'DJE', 'FLO', 'FNC', 'GAL', 'GIB', 'GOT', 'HAD', 'HAG', 'HOR', 'INC', 'JAF', 'JEJ', 'KUP', 'LGA', 'LPA', 'MAC', 'MAN', 'MAT', 'MLE', 'MOK', 'MWY', 'NAH', 'NEW', 'OSA', 'PAL', 'PLM', 'PLO', 'PON', 'PRT', 'PTT', 'PUS', 'RHO', 'RIG', 'SAK', 'SAO', 'SGO', 'STG', 'STO', 'SUR', 'TAL', 'TAN', 'TEN', 'TON', 'TOR', 'TOU', 'TRA', 'TRP', 'TSU', 'TUR', 'VAR', 'VIS', 'VLL', 'WIL', 'ZAK', 'ZAN');

